// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Read the register": "in1_Readtheregister", "Read the verified list": "in2_Readtheverifiedlist", "Read staff accounts": "in3_Readstaffaccounts"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Read staff accounts";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
DATA['Step 1: List verified'] = [{ json: { body: { series_id: input.ev_series_id, occurrence_id: input.ev_occurrence_id, verified_by: input.ev_verified_by } } }];
// One stamp for the run: every task-ID write-back carries it, so step 8 finds this run's new tasks.
const STAMP = new Date().toISOString();
const BODIES = (out) => ({"stamp": STAMP, "item_q": encodeURIComponent(out.item_id || ''), "refuse_exception": JSON.stringify({ recipe: 'R14.2', item: $('Step 1: List verified').first().json.body.occurrence_id, reason: 'verifier not chair or backup', detail: out.reason + ': ' + $('Step 1: List verified').first().json.body.verified_by, owner: $('Config').first().json.register_owner }), "refuse_message": JSON.stringify({ to: [$('Config').first().json.register_owner], subject: 'Action list not verified by its chair or backup', text: 'No tasks created for meeting ' + $('Step 1: List verified').first().json.body.occurrence_id + ': ' + out.reason + ' (' + $('Step 1: List verified').first().json.body.verified_by + ').' }), "return_body": JSON.stringify({ status: 'returned', return_reason: (out.reasons || []).join('; ') }), "log_returned": JSON.stringify(Object.assign({ recipe: 'R14.2', item: out.item_id, approved_by: out.verified_by, decision: 'returned to chair' }, { rules: { reasons: out.reasons } })), "minutes_body": JSON.stringify(out.minutes || {}), "task_body": JSON.stringify({ title: out.title, owner: out.task_owner, owner_email: out.task_email, due_date: out.due_date, verified_due_date: out.due_date, series: out.series, series_id: out.series_id, source_link: out.source_link, item_id: out.item_id, quoted_line: out.quoted_line, verified_by: out.verified_by, status: 'open' }), "created_body": JSON.stringify({ task_id: '__TASK_ID__', verified_due_date: out.due_date, verified_at: STAMP }), "found_body": JSON.stringify({ task_id: '__TASK_ID__' }), "log_created": JSON.stringify(Object.assign({ recipe: 'R14.2', item: out.item_id, approved_by: out.verified_by, decision: 'task created' }, { rules: { task_id: '__TASK_ID__', route: out.route } })), "log_found": JSON.stringify(Object.assign({ recipe: 'R14.2', item: out.item_id, approved_by: out.verified_by, decision: 'existing task linked' }, { rules: { task_id: '__TASK_ID__', route: out.route } })), "task_error": JSON.stringify({ recipe: 'R14.2', item: out.item_id, reason: 'task system error', detail: 'Task system failed after one retry', owner: out.chair }), "task_error_message": JSON.stringify({ to: [out.chair], subject: 'Task not created: ' + out.series, text: 'The task system failed after one retry for: ' + out.title + '. Owen reruns the list; items with a task ID are skipped.' }), "write_failed": JSON.stringify({ recipe: 'R14.2', item: $('Step 1: List verified').first().json.body.occurrence_id, reason: 'write failed', detail: 'A write or message failed; never retried. Check the list, then rerun it: steps 5 and 6 guard.', owner: $('Config').first().json.exception_owner })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Steps 2 to 5 of the book's R14.2 and the checks in Table 14.1. The workflow never fills a gap.
const ev = $('Step 1: List verified').first().json.body;
const series = ($('Read the register').first().json.items || [])[0] || null;
const staff = $('Read staff accounts').first().json.items || [];
const items = ($('Read the verified list').first().json.items || []).filter(i => i.status === 'approved');
const today = new Date().toISOString().slice(0, 10);
const low = s => String(s || '').trim().toLowerCase();

// Step 2: the verifier must be the series' chair or backup.
if (!series || ![series.chair, series.backup].map(low).includes(low(ev.verified_by))) {
  return [{ json: { route: 'refuse', reason: series ? 'verifier not chair or backup' : 'series not in the register', verified_by: ev.verified_by } }];
}
const chair = staff.find(s => low(s.email) === low(series.chair)) || { name: series.chair, email: series.chair };

// The owner as a staff account: full name or address, else a unique first-name match.
function account(owner) {
  const o = low(owner);
  const exact = staff.filter(s => low(s.name) === o || low(s.email) === o);
  if (exact.length) return { acct: exact[0] };
  const first = staff.filter(s => low(s.name).split(/\s+/)[0] === o);
  if (first.length > 1) return { ambiguous: true };
  return { acct: first[0] || null };
}
const isDate = d => /^\d{4}-\d{2}-\d{2}$/.test(d || '') && !isNaN(Date.parse(d + 'T00:00:00Z'))
  && new Date(d + 'T00:00:00Z').toISOString().slice(0, 10) === d;

const out = [];
for (const it of items) {
  // Step 5: an item already holding a task ID is skipped, whatever steps 3 and 4 would say.
  if (it.task_id) continue;
  const owner = String(it.owner || '').trim();
  const { acct, ambiguous } = account(owner);
  const base = { item_id: it.id, action: String(it.action || '').trim(), owner, due_date: it.due_date || '',
                 source_link: it.source_link || '', quoted_line: it.quoted_line || '' };
  // Step 3: an owner outside the company goes into the minutes, with a follow-up task for the chair.
  if (owner && low(owner) !== 'unassigned' && !acct && !ambiguous) {
    out.push({ ...base, route: 'outside', task_owner: chair.name, task_email: chair.email,
               title: `Follow up with ${owner}: ${base.action}`,
               minutes: { id: it.id, occurrence_id: it.occurrence_id, series_id: series.id,
                          text: `${owner} (outside the company): ${base.action}${base.due_date ? ', due ' + base.due_date : ''}`,
                          source_link: base.source_link } });
    continue;
  }
  // Step 4: Table 14.1. A failure returns the item to the chair with the reason.
  const reasons = [];
  if (!base.action) reasons.push('no action');
  if (!owner || low(owner) === 'unassigned') reasons.push('no owner');
  else if (ambiguous) reasons.push('owner matches more than one staff account');
  else if (!acct.active) reasons.push('owner not an active staff account');
  if (!isDate(base.due_date)) reasons.push('due date is not a calendar date');
  else if (base.due_date < today) reasons.push('due date is in the past');
  if (!base.source_link) reasons.push('no source link');
  if (reasons.length) { out.push({ ...base, route: 'return', reasons }); continue; }
  out.push({ ...base, route: 'task', task_owner: acct.name, task_email: acct.email, title: base.action });
}
return out.map(j => ({ json: { ...j, series_id: series.id, series: series.name, chair: series.chair, verified_by: ev.verified_by } }));
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };

